<template>
  <section class="pos-terminal" aria-label="Point of sale">
    <div class="pos-catalog" :inert="compact && panelOpen ? '' : null">
      <div class="pos-catalog-heading"><div><div class="pos-eyebrow">PAHATUD POINT OF SALE</div><h1>Let’s take an order</h1><p>Good food, just a tap away.</p></div><div class="pos-catalog-actions"><span class="pos-menu-count">{{ data.menu.length }} menu items</span><button type="button" class="btn pos-fullscreen-toggle" :aria-label="fullscreen ? 'Exit POS full screen' : 'POS full screen'" :aria-pressed="fullscreen" @click="$emit('toggle-fullscreen')"><pos-icon name="expand" />{{ fullscreen ? 'Exit full screen' : 'Full screen' }}</button></div></div>
      <label class="pos-search"><pos-icon name="search" /><input v-model="search" type="search" placeholder="Search food, drinks, and more…" aria-label="Search products"><kbd>/</kbd></label>
      <nav class="pos-categories" aria-label="Product categories"><button type="button" :class="{active: category === 'all'}" :aria-pressed="category === 'all'" @click="category = 'all'">All items <span>{{ data.menu.length }}</span></button><button v-for="c in categories" :key="c.id" type="button" :class="{active: category === c.id}" :aria-pressed="category === c.id" @click="category = c.id">{{ c.name }} <span>{{ c.count }}</span></button></nav>
      <div class="pos-results"><strong>{{ categoryName }}</strong><span>{{ products.length }} {{ products.length === 1 ? 'item' : 'items' }}</span></div>
      <div v-if="products.length" class="pos-product-grid">
        <button v-for="product in products" :key="product.id" type="button" class="pos-product-card" :aria-label="'Customize ' + product.name + ', ' + money(product.price)" :disabled="busy || !!submitted" @click="customize(product, $event)">
          <div class="pos-product-photo"><img v-if="product.image && !failedImages[product.id]" :src="product.image" alt="" loading="lazy" @error="$set(failedImages, product.id, true)"><div v-else class="pos-photo-placeholder"><pos-icon name="chef" /><span>Fresh from the menu</span></div><span class="pos-product-add" aria-hidden="true">+</span></div>
          <div class="pos-product-copy"><small>{{ product.category }}</small><h2>{{ product.name }}</h2><div><strong>{{ money(product.price) }}</strong><span v-if="product.variants.length">Customize <span aria-hidden="true">↗</span></span></div></div>
        </button>
      </div>
      <div v-else class="pos-empty-products"><pos-icon name="search" /><h2>{{ data.menu.length ? 'No items found' : 'Your menu is empty' }}</h2><p>{{ data.menu.length ? 'Try another name or category.' : 'Available branch products will appear here.' }}</p><button v-if="data.menu.length" type="button" @click="search = ''; category = 'all'">Clear filters</button></div>
    </div>

    <button v-if="compact && panelOpen" class="pos-scrim" type="button" aria-label="Dismiss order overlay" tabindex="-1" @click="closePanel"></button>
    <aside ref="panel" class="pos-order-panel" :class="{'is-open': panelOpen}" :role="compact && panelOpen ? 'dialog' : 'complementary'" :aria-modal="compact && panelOpen ? 'true' : null" aria-labelledby="pos-panel-title" @keydown="panelKeydown">
      <header class="pos-panel-heading"><div><div class="pos-eyebrow">{{ draft ? 'MAKE IT THEIR OWN' : submitted ? 'SENT TO THE KITCHEN' : 'A FRESH START' }}</div><h2 id="pos-panel-title" ref="panelTitle" tabindex="-1">{{ draft ? 'Customize item' : submitted ? 'Order #' + submitted.number : 'Current order' }} <span v-if="!draft && !submitted" class="pos-item-count">{{ itemCount }}</span></h2></div><button class="pos-panel-close" type="button" aria-label="Close order panel" :disabled="busy" @click="closePanel">×</button></header>

      <form v-if="draft" class="pos-customizer" @submit.prevent="saveItem">
        <div class="pos-panel-scroll">
          <div class="pos-detail-photo"><img v-if="draft.product.image && !failedImages[draft.product.id]" :src="draft.product.image" alt="" @error="$set(failedImages, draft.product.id, true)"><div v-else class="pos-photo-placeholder"><pos-icon name="chef" /></div></div>
          <div class="pos-detail-title"><h3>{{ draft.product.name }}</h3><strong>{{ money(draft.product.price) }}</strong></div><p v-if="draft.product.description" class="pos-description">{{ draft.product.description }}</p>
          <div class="pos-quantity-row"><label for="pos-quantity">Quantity</label><div class="pos-stepper"><button type="button" aria-label="Decrease quantity" :disabled="draft.qty <= 1" @click="draft.qty--">−</button><input id="pos-quantity" v-model.number="draft.qty" type="number" min="1" max="100" required><button type="button" aria-label="Increase quantity" :disabled="draft.qty >= 100" @click="draft.qty++">+</button></div></div>
          <fieldset v-for="group in draft.product.variants" :key="group.id" class="pos-options"><legend>{{ group.name }} <small>{{ group.required ? 'Required' : 'Optional' }} · {{ group.multiple ? 'Choose any' : 'Choose one' }}</small></legend>
            <label v-if="!group.multiple && !group.required" class="pos-option"><input v-model="draft.options[group.id]" type="radio" :name="'variant-' + group.id" value=""><span>No selection</span></label>
            <label v-for="option in group.options" :key="option.id" class="pos-option" :class="{selected: optionSelected(group, option.id)}"><input v-if="group.multiple" v-model="draft.options[group.id]" type="checkbox" :value="option.id"><input v-else v-model="draft.options[group.id]" type="radio" :name="'variant-' + group.id" :value="option.id" :required="group.required"><span>{{ option.name }}</span><strong>{{ option.price ? '+ ' + money(option.price) : 'Included' }}</strong></label>
          </fieldset>
          <label class="pos-field">Special instructions <small>For this item only</small><textarea v-model.trim="draft.instruction" maxlength="250" rows="3" placeholder="e.g. No onions, sauce on the side"></textarea></label>
          <p v-if="customError" class="pos-error" role="alert">{{ customError }}</p>
        </div>
        <footer class="pos-panel-footer"><button class="pos-checkout" type="submit"><span>{{ editingIndex === null ? 'Add to order' : 'Save item' }}</span><strong>{{ money(draftTotal) }}</strong></button><button class="pos-secondary" type="button" @click="draft = null">Back to order</button></footer>
      </form>

      <form v-else-if="!submitted" class="pos-basket-form" @submit.prevent="submit">
        <div class="pos-panel-scroll">
          <div class="pos-order-types" role="group" aria-label="Order type"><button v-for="option in data.fulfillment_types" :key="option.type" type="button" :class="{active: type === option.type}" :aria-pressed="type === option.type" :disabled="busy" @click="type = option.type"><pos-icon :name="option.type === 'dine_in' ? 'table' : option.type === 'pickup' ? 'orders' : 'pin'" />{{ option.label }}</button></div>
          <label v-if="type === 'dine_in'" class="pos-field pos-table-field">Dining table<select v-model="table" required :disabled="busy"><option value="" disabled>Select a table</option><option v-for="t in data.tables.filter(t => t.active && t.is_available)" :key="t.id" :value="t.id">{{ t.name }}</option></select></label>
          <div v-if="!lines.length" class="pos-empty-basket"><div><pos-icon name="orders" /></div><h3>Something delicious starts here</h3><p>Tap a menu item to customize it<br>and add it to this order.</p></div>
          <div v-else class="pos-basket-lines"><article v-for="(line, index) in lines" :key="line.key" class="pos-basket-line"><div class="pos-line-top"><button type="button" :disabled="busy" :aria-label="'Edit ' + line.product.name" @click="editItem(index)"><strong>{{ line.product.name }}</strong></button><strong>{{ money(lineTotal(line)) }}</strong></div><p v-if="optionNames(line).length">{{ optionNames(line).join(' · ') }}</p><p v-if="line.instruction" class="pos-line-note">{{ line.instruction }}</p><div class="pos-line-controls"><div class="pos-stepper"><button type="button" :aria-label="'Decrease ' + line.product.name" :disabled="busy || line.qty <= 1" @click="line.qty--">−</button><span>{{ line.qty }}</span><button type="button" :aria-label="'Increase ' + line.product.name" :disabled="busy || line.qty >= 100" @click="line.qty++">+</button></div><button class="pos-remove" type="button" :disabled="busy" :aria-label="'Remove ' + line.product.name" @click="lines.splice(index, 1)">Remove</button></div></article></div>
          <details class="pos-customer" :open="type === 'delivery'"><summary>{{ type === 'delivery' ? 'Customer & delivery details' : 'Customer details' }} <small>{{ type === 'delivery' ? 'Required' : 'Optional' }}</small></summary><div class="pos-form-fields"><label class="pos-field">Customer name<input v-model.trim="name" :disabled="busy" maxlength="150" placeholder="Walk-in customer"></label><label class="pos-field">Mobile<input v-model.trim="mobile" :disabled="busy" :required="type === 'delivery'" maxlength="30" type="tel" placeholder="09XX XXX XXXX"></label><template v-if="type === 'delivery'"><label class="pos-field">Delivery address<input v-model.trim="address" :disabled="busy" required maxlength="250"></label><div class="pos-coordinate-fields"><label class="pos-field">Latitude<input v-model="lat" :disabled="busy" type="number" step="any" min="-90" max="90" required></label><label class="pos-field">Longitude<input v-model="long" :disabled="busy" type="number" step="any" min="-180" max="180" required></label></div><label class="pos-field">Delivery fee (₱)<input v-model.number="fee" :disabled="busy" type="number" step="0.01" min="0" max="99999" required></label></template></div></details>
          <label class="pos-field pos-order-note">Order notes<textarea v-model.trim="notes" :disabled="busy" maxlength="2000" rows="2" placeholder="Instructions for the whole order"></textarea></label>
          <label class="pos-field">Payment preference<select v-model="payment" :disabled="busy" required><option disabled value="">Select method</option><option v-for="m in data.payment_methods" :key="m.id" :value="m.id">{{ m.title }}</option></select></label>
        </div>
        <footer class="pos-panel-footer"><div v-if="quote" class="pos-totals"><div><span>Subtotal</span><span>{{ money(quote.sub_total) }}</span></div><div v-if="quote.delivery_fee"><span>Delivery</span><span>{{ money(quote.delivery_fee) }}</span></div><div v-if="quote.convenience_fee - quote.vat_amount"><span>Fees</span><span>{{ money(quote.convenience_fee - quote.vat_amount) }}</span></div><div v-if="quote.discount"><span>Discount</span><span>−{{ money(quote.discount) }}</span></div><div v-if="existingBill"><span>Earlier table rounds</span><span>{{ money(existingBill.totals.total) }}</span></div><div class="pos-grand-total"><strong>Total due</strong><strong>{{ money(quotedTotal) }}</strong></div></div><p v-if="error" class="pos-error" role="alert">{{ error }}</p><button v-if="error && !quote && !quoting" type="button" class="pos-secondary" @click="retryQuote">Retry total</button><button class="pos-checkout" type="submit" :disabled="!lines.length || !quote || quoting || busy || disabled"><span>{{ busy ? 'Sending order…' : quoting ? 'Updating total…' : 'Send to kitchen' }}</span><pos-icon name="arrow" /></button><p class="pos-checkout-hint">Review the bill and collect payment here after service.</p></footer>
      </form>

      <div v-else class="pos-submitted">
        <div class="pos-panel-scroll">
          <div class="pos-sent-status" :class="{paid: bill && bill.paid}"><pos-icon name="check" /><div><strong>{{ bill && bill.paid ? 'Payment complete' : 'Order received by the kitchen' }}</strong><small>{{ bill && bill.paid ? 'Your receipt is ready.' : 'This order is saved. Kitchen updates appear here.' }}</small></div></div>
          <div v-if="bill" class="pos-submitted-items"><div v-for="round in bill.orders" :key="round.id" class="pos-submitted-round"><div class="pos-round-heading"><strong>#{{ round.number }}</strong><span class="badge" :class="orderStatus(round.id)">{{ statusLabel(orderStatus(round.id)) }}</span></div><article v-for="(item, index) in round.items" :key="index" class="pos-paid-line"><div><span>{{ item.qty }}× {{ item.name }}</span><strong>{{ money(item.qty * item.unit_price) }}</strong></div><small v-if="item.variants">{{ item.variants }}</small><small v-if="item.note">{{ item.note }}</small></article><button v-if="canServe(round.id) && data.abilities.serve" class="pos-secondary" type="button" :disabled="busy" @click="serve(round.id)">{{ type === 'pickup' ? 'Complete pickup' : 'Mark served' }}</button></div></div>
          <p v-if="submittedNotes" class="pos-saved-note"><b>Order notes:</b> {{ submittedNotes }}</p>
          <div v-if="bill && !bill.paid" class="pos-payment-section"><h3>Collect payment</h3><p v-if="!payable" class="pos-payment-wait">{{ type === 'delivery' ? 'Payment becomes available when the kitchen marks this order ready, before rider handoff.' : 'Waiting for the kitchen. Complete service when the order is ready to collect payment.' }}</p><form @submit.prevent="pay"><label class="pos-field">Payment method<select v-model="payment" :disabled="busy" required @change="cash = ''; reference = ''; paymentKey = null"><option v-for="m in data.payment_methods" :key="m.id" :value="m.id">{{ m.title }}</option></select></label><template v-if="isCash"><label class="pos-field">Cash tendered (₱)<input v-model="cash" :disabled="busy" type="number" min="0" step="0.01" required inputmode="decimal" placeholder="0.00"></label><div class="pos-change"><span>{{ cashCents < bill.totals.total ? 'Still due' : 'Change due' }}</span><strong>{{ money(Math.abs(cashCents - bill.totals.total)) }}</strong></div></template><label v-else class="pos-field">Payment reference<input v-model.trim="reference" :disabled="busy" maxlength="150" placeholder="Transaction reference"></label><p class="pos-checkout-hint">Record payment after confirming it was received.</p><button class="pos-checkout" :disabled="busy || !payable || (isCash && (cash === '' || cashCents < bill.totals.total))">{{ busy ? 'Recording…' : 'Confirm payment' }}</button></form></div>
          <div v-if="bill && bill.paid && bill.payment" class="pos-payment-summary"><div><span>Payment</span><strong>{{ bill.payment.method }}</strong></div><div v-if="bill.payment.cash_tendered !== null"><span>Cash tendered</span><strong>{{ money(bill.payment.cash_tendered) }}</strong></div><div v-if="bill.payment.change !== null"><span>Change</span><strong>{{ money(bill.payment.change) }}</strong></div></div>
          <p v-if="error" class="pos-error" role="alert">{{ error }}</p>
        </div>
        <footer class="pos-panel-footer"><div v-if="bill" class="pos-totals"><div><span>Subtotal</span><span>{{ money(bill.totals.sub_total) }}</span></div><div><span>Delivery & fees</span><span>{{ money(bill.totals.delivery_fee + bill.totals.convenience_fee - bill.totals.vat_amount) }}</span></div><div v-if="bill.totals.discount"><span>Discount</span><span>−{{ money(bill.totals.discount) }}</span></div><div class="pos-grand-total"><strong>{{ bill.paid ? 'Total paid' : 'Total due' }}</strong><strong>{{ money(bill.totals.total) }}</strong></div></div><button v-if="bill && bill.paid" class="pos-checkout" type="button" :disabled="busy" @click="$emit('receipt', submitted.bill_id)"><pos-icon name="print" />View receipt</button><button v-else class="pos-secondary" type="button" :disabled="busy" @click="refreshBill">Refresh bill</button><button class="pos-secondary" type="button" :disabled="busy" @click="newOrder">{{ bill && bill.paid ? 'Start new order' : 'Take another order · leave this bill open' }}</button></footer>
      </div>
    </aside>
    <button v-if="compact && !panelOpen" type="button" class="pos-mobile-order" @click="showPanel"><pos-icon name="orders" /><span>{{ submitted ? 'Review order #' + submitted.number : 'View order · ' + itemCount + (itemCount === 1 ? ' item' : ' items') }}</span><strong>{{ money(bill ? bill.totals.total : quotedTotal) }}</strong><span aria-hidden="true">↑</span></button>
  </section>
</template>

<script>
import axios from 'axios';
import paths from './icons';
const PosIcon = {functional: true, props: ['name'], render(h, context) { return h('svg', {attrs: {viewBox: '0 0 24 24', 'aria-hidden': 'true'}}, [h('path', {attrs: {d: paths[context.props.name] || paths.orders}})]); }};
function requestId() { const b = crypto.getRandomValues(new Uint8Array(16)); b[6] = (b[6] & 15) | 64; b[8] = (b[8] & 63) | 128; const h = Array.from(b, v => v.toString(16).padStart(2, '0')).join(''); return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`; }
export default {
  components: {PosIcon}, props: ['data', 'endpoint', 'disabled', 'fullscreen'],
  data() { return {search: '', category: 'all', failedImages: {}, type: (this.data.fulfillment_types.find(t => t.type === 'dine_in') || this.data.fulfillment_types[0])?.type || '', table: '', payment: (this.data.payment_methods.find(m => m.is_cash) || this.data.payment_methods[0])?.id || '', name: '', mobile: '', address: '', lat: '', long: '', fee: 0, notes: '', lines: [], draft: null, editingIndex: null, customError: '', quote: null, quoting: false, quoteTimer: null, quoteSequence: 0, busy: false, error: '', key: null, submitted: null, submittedNotes: '', bill: null, billLoading: false, paymentKey: null, cash: '', reference: '', compact: false, panelOpen: false, media: null, returnFocus: null}; },
  computed: {
    categories() { const groups = new Map(); this.data.menu.forEach(p => { const id = String(p.category_id || 'other'); if (!groups.has(id)) groups.set(id, {id, name: p.category, count: 0}); groups.get(id).count++; }); return [...groups.values()]; },
    categoryName() { return this.category === 'all' ? 'Explore the menu' : this.categories.find(c => c.id === this.category)?.name || 'Menu'; },
    products() { const q = this.search.trim().toLowerCase(); return this.data.menu.filter(p => (this.category === 'all' || String(p.category_id || 'other') === this.category) && (!q || `${p.name} ${p.category} ${p.description}`.toLowerCase().includes(q))); },
    itemCount() { return this.lines.reduce((n, line) => n + line.qty, 0); },
    draftTotal() { return this.draft ? this.lineTotal(this.draft) : 0; },
    existingBill() { return this.type === 'dine_in' && this.table ? this.data.bills.find(b => b.table_id === this.table) : null; },
    quotedTotal() { return (this.quote?.total || 0) + (this.existingBill?.totals.total || 0); },
    draftSignature() { return JSON.stringify({fulfillment_type: this.type, delivery_fee: this.type === 'delivery' ? this.fee : 0, items: this.serializeItems()}); },
    isCash() { return !!this.data.payment_methods.find(m => String(m.id) === String(this.payment))?.is_cash; },
    cashCents() { return Math.max(0, Math.round(Number(this.cash || 0) * 100)); },
    payable() { return !!this.bill && !this.bill.paid && this.bill.orders.length > 0 && this.bill.orders.every(round => { const order = this.data.orders.find(o => o.id === round.id); return order && (order.status === 'served' || (order.type === 'delivery' && order.status === 'ready')); }); },
  },
  watch: {
    draftSignature() { clearTimeout(this.quoteTimer); const sequence = ++this.quoteSequence; this.quote = null; this.error = ''; if (!this.lines.length || this.submitted) { this.quoting = false; return; } this.quoting = true; this.quoteTimer = setTimeout(() => this.getQuote(sequence), 250); },
    'data.updated_at'() { if (this.submitted) this.refreshBill(); },
    busy(value) { this.$emit('busy', value); },
  },
  mounted() { this.media = window.matchMedia('(max-width: 899px)'); this.resize(); this.media.addEventListener('change', this.resize); window.addEventListener('keydown', this.searchShortcut); },
  beforeDestroy() { clearTimeout(this.quoteTimer); this.quoteSequence++; this.media?.removeEventListener('change', this.resize); window.removeEventListener('keydown', this.searchShortcut); this.$emit('busy', false); },
  methods: {
    money(n) { return '₱' + (Number(n || 0) / 100).toLocaleString('en-PH', {minimumFractionDigits: 2, maximumFractionDigits: 2}); },
    url(suffix) { const url = new URL(this.endpoint, window.location.origin); url.pathname = url.pathname.replace(/\/orders$/, suffix); return url.toString(); },
    headers() { return {'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content, Accept: 'application/json'}; },
    message(e) { const data = e.response?.data; return data?.errors ? Object.values(data.errors).flat()[0] : data?.message || 'Unable to connect. Please retry.'; },
    resize() { this.compact = this.media.matches; },
    searchShortcut(event) { if (event.key === '/' && !/INPUT|TEXTAREA|SELECT/.test(event.target.tagName) && !(this.compact && this.panelOpen)) { event.preventDefault(); this.$el.querySelector('input[type="search"]').focus(); } },
    showPanel() { this.panelOpen = true; this.$nextTick(() => this.$refs.panelTitle?.focus({preventScroll: true})); },
    closePanel() { if (this.busy) return; this.panelOpen = false; this.returnFocus?.focus(); },
    panelKeydown(event) { if (!this.compact || !this.panelOpen) return; if (event.key === 'Escape') { event.preventDefault(); this.closePanel(); } if (event.key !== 'Tab') return; const controls = Array.from(this.$refs.panel.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')).filter(el => el.getClientRects().length); const first = controls[0], last = controls[controls.length - 1]; if (event.shiftKey && (document.activeElement === first || document.activeElement === this.$refs.panelTitle)) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } },
    customize(product, event) { if (this.busy || this.submitted) return; this.returnFocus = event?.currentTarget; this.editingIndex = null; this.customError = ''; const options = {}; product.variants.forEach(g => { options[g.id] = g.multiple ? [] : ''; }); this.draft = {product, qty: 1, options, instruction: '', key: requestId()}; this.showPanel(); },
    editItem(index) { this.editingIndex = index; this.customError = ''; const line = this.lines[index]; this.draft = {...line, options: JSON.parse(JSON.stringify(line.options))}; this.showPanel(); },
    optionSelected(group, id) { const selection = this.draft.options[group.id]; return Array.isArray(selection) ? selection.includes(id) : selection === id; },
    chosenOptions(line) { return line.product.variants.flatMap(g => g.options.filter(o => Array.isArray(line.options[g.id]) ? line.options[g.id].includes(o.id) : line.options[g.id] === o.id)); },
    optionNames(line) { return this.chosenOptions(line).map(o => o.name); },
    lineTotal(line) { return (line.product.price + this.chosenOptions(line).reduce((n, o) => n + o.price, 0)) * line.qty; },
    saveItem() { const missing = this.draft.product.variants.find(g => g.required && (!this.draft.options[g.id] || (Array.isArray(this.draft.options[g.id]) && !this.draft.options[g.id].length))); if (missing) { this.customError = 'Choose an option for ' + missing.name + '.'; return; } if (!Number.isInteger(this.draft.qty) || this.draft.qty < 1 || this.draft.qty > 100) return; if (this.editingIndex === null) this.lines.push(this.draft); else this.$set(this.lines, this.editingIndex, this.draft); this.draft = null; this.error = ''; },
    serializeItems() { return this.lines.map(line => ({product_id: line.product.id, qty: line.qty, instruction: line.instruction, selections: line.product.variants.flatMap(g => (Array.isArray(line.options[g.id]) ? line.options[g.id] : [line.options[g.id]]).filter(Boolean).map(id => ({variant_id: g.id, product_detail_id: id})))})); },
    retryQuote() { if (!this.lines.length || this.busy) return; clearTimeout(this.quoteTimer); this.quoting = true; this.getQuote(++this.quoteSequence); },
    async getQuote(sequence) { try { const response = await axios.post(this.url('/pos/quote'), JSON.parse(this.draftSignature), {headers: this.headers()}); if (sequence === this.quoteSequence) { this.quote = response.data.totals; this.error = ''; } } catch (e) { if (sequence === this.quoteSequence) this.error = this.message(e); } finally { if (sequence === this.quoteSequence) this.quoting = false; } },
    async submit() { if (this.busy || this.disabled || this.quoting || !this.quote || !this.lines.length) return; this.busy = true; this.error = ''; this.key = this.key || requestId(); try { const response = await axios.post(this.endpoint, {idempotency_key: this.key, fulfillment_type: this.type, dining_table_id: this.type === 'dine_in' ? this.table : null, payment_method_id: this.payment, fullname: this.name || null, mobile: this.mobile || null, address: this.address || null, lat: this.lat || null, long: this.long || null, delivery_fee: this.fee, notes: this.notes || null, items: this.serializeItems()}, {headers: this.headers()}); this.submitted = response.data; this.submittedNotes = this.notes; this.paymentKey = requestId(); this.$emit('created'); await this.refreshBill(); } catch (e) { this.error = this.message(e); if (e.response && e.response.status < 500) this.key = null; } finally { this.busy = false; } },
    async refreshBill() { if (!this.submitted?.bill_id || this.billLoading) return; this.billLoading = true; try { const response = await axios.get(this.url('/bills/' + this.submitted.bill_id + '/receipt'), {headers: this.headers()}); this.bill = response.data; } catch (e) { this.error = this.message(e); } finally { this.billLoading = false; } },
    orderStatus(id) { return this.data.orders.find(o => o.id === id)?.status || 'new'; },
    statusLabel(status) { return {new: 'New order', preparing: 'Preparing', ready: 'Ready', served: 'Completed', cancelled: 'Cancelled', on_the_way: 'With rider', arrived: 'At customer'}[status] || status; },
    canServe(id) { const order = this.data.orders.find(o => o.id === id); return order?.status === 'ready' && order.type !== 'delivery'; },
    async serve(id) { if (this.busy) return; this.busy = true; this.error = ''; try { await axios.post(this.url('/orders/' + id + '/transition'), {action: 'served', expected_status: 4}, {headers: this.headers()}); this.$emit('created'); await this.refreshBill(); } catch (e) { this.error = this.message(e); } finally { this.busy = false; } },
    async pay() { if (!this.payable || this.busy) return; this.busy = true; this.error = ''; this.paymentKey = this.paymentKey || requestId(); try { await axios.post(this.url('/bills/' + this.submitted.bill_id + '/payment'), {payment_method_id: this.payment, idempotency_key: this.paymentKey, expected_total: this.bill.totals.total, cash_tendered_cents: this.isCash ? this.cashCents : null, reference: this.isCash ? null : this.reference || null}, {headers: this.headers()}); await this.refreshBill(); this.$emit('created'); } catch (e) { this.error = this.message(e); await this.refreshBill(); } finally { this.busy = false; } },
    newOrder() { if (this.busy) return; this.submitted = null; this.bill = null; this.submittedNotes = ''; this.lines = []; this.draft = null; this.quote = null; this.key = null; this.paymentKey = null; this.notes = ''; this.cash = ''; this.reference = ''; this.name = ''; this.mobile = ''; this.address = ''; this.lat = ''; this.long = ''; this.fee = 0; this.table = ''; this.error = ''; this.panelOpen = false; },
  },
};
</script>
